const data = $('Get Split Info').first().json;
const config = data.size?.configs?.find(c => c.config === 'base_set');
const total = config?.num_rows ?? 0;
if (!total) {
  return [{ json: { offset: 0, total: 0, error: 'No rows found for base_set' } }];
}
const offset = Math.floor(Math.random() * total);
return [{ json: { offset, total, config: 'base_set', split: 'train' } }];

const data = $('Fetch Random Prompt').first().json;
const row = data.rows?.[0]?.row;
if (!row) {
  return [{ json: { error: 'No prompt found in dataset.' } }];
}

const promptText = row.question || row.augq || row.daugq || row.mcq || JSON.stringify(row);
const source = row.source || row.method || row.dmethod || '—';
const cat1 = row['1-category'] || '—';
const cat2 = row['2-category'] || '—';
const cat3 = row['3-category'] || '—';

// Return both the prompt metadata AND the Lakera Guard API payload
return [{
  json: {
    prompt: promptText,
    source: source,
    category1: cat1,
    category2: cat2,
    category3: cat3,
    // Lakera Guard expects: { messages: [{ role, content }], breakdown: true }
    messages: [{ role: 'user', content: promptText }],
    breakdown: true,
  }
}];

var items = $input.all();

// Grab the prompt metadata from earlier in the workflow
var promptInfo = $('Extract Prompt').first().json;
var promptText = promptInfo.prompt || 'Unknown';
var source = promptInfo.source || '—';
var cat1 = promptInfo.category1 || '—';
var cat2 = promptInfo.category2 || '—';
var cat3 = promptInfo.category3 || '—';

// Build classification tree display
var classificationLine = '';
if (cat1 !== '—' || cat2 !== '—' || cat3 !== '—') {
  classificationLine = '\n\n**Classification:**\n';
  if (cat1 !== '—') classificationLine += '  ▶ ' + cat1 + '\n';
  if (cat2 !== '—') classificationLine += '    ▶ ' + cat2 + '\n';
  if (cat3 !== '—') classificationLine += '      ▶ ' + cat3 + '\n';
}

var results = [];
for (var i = 0; i < items.length; i++) {
  var data = items[i].json;
  var flagged = data.flagged === true;

  // Build detection details from breakdown
  var detections = '';
  var riskScore = 'None';
  if (data.breakdown && Array.isArray(data.breakdown)) {
    var detected = [];
    var scores = [];
    for (var k = 0; k < data.breakdown.length; k++) {
      var b = data.breakdown[k];
      if (b.detected === true) { detected.push(b); }
      if (typeof b.risk_score === 'number') { scores.push(b.risk_score); }
    }

    if (detected.length > 0) {
      var lines = [];
      for (var j = 0; j < detected.length; j++) {
        var d = detected[j];
        var line = '• [' + (d.detector_id || d.detector_type || 'unknown') + ']';
        if (d.detected_class) { line = line + ' - ' + d.detected_class; }
        if (typeof d.risk_score === 'number') {
          var pct = Math.round(d.risk_score * 100);
          line = line + ' (confidence: ' + pct + '%)';
        }
        lines.push(line);
      }
      detections = '\n\n**Triggered Detectors:**\n' + lines.join('\n');
    }

    if (scores.length > 0) {
      var maxScore = Math.max.apply(null, scores);
      if (maxScore >= 0.8) { riskScore = 'Critical'; }
      else if (maxScore >= 0.5) { riskScore = 'High'; }
      else if (maxScore >= 0.2) { riskScore = 'Medium'; }
      else { riskScore = 'Low'; }
    }
  }

  // Build chat response
  var header = '🎰 **Prompt Roulette V2**🎰\n\n';
  var promptSection = '📝 **Random Prompt:**\n> ' + promptText;
  var sourceLine = '\n📋 **Source:** ' + source;

  var verdictSection;
  if (flagged) {
    var threatIcon = '🔴';
    verdictSection = '\n\n' + threatIcon + ' **Lakera Verdict: THREAT DETECTED** ' + threatIcon
      + '\nThis prompt was flagged as potentially harmful.'
      + detections;
  } else {
    var safeIcon = '🟢';
    verdictSection = '\n\n' + safeIcon + ' **Lakera Verdict: SAFE** ✅'
      + '\nNo threats detected in this prompt.';
  }

  var riskLine = '\n\n**Risk Score:** ' + riskScore;

  var output = header + promptSection + sourceLine + classificationLine + verdictSection + riskLine;

  results.push({
    json: {
      output: output,
      flagged: flagged,
      riskScore: riskScore,
      prompt: promptText,
      source: source,
      category1: cat1,
      category2: cat2,
      category3: cat3,
    }
  });
}
return results;
